/* ⚠️ A GOTA TEM QUE SUMIR DEPOIS DE CAIR (defeito visto no print): a animacao
   acaba e o elemento volta ao lugar de partida, entao as tres gotas ficavam
   PENDURADAS no ceu para sempre, como se a chuva tivesse congelado. Some com
   elas no fim — e com guarda de geracao, que a cena pode ter trocado. */
function chuva(g){
  var i, base=(R.cena==="canteiro"?"cgota":"bgota");
  if(!CE.gotas) return;
  for(i=0;i<CE.gotas.length;i++){
    (function(e,n){
      setTimeout(function(){ if(g===ger) e.className=base+" pap_on"; },n*140);
      setTimeout(function(){ if(g===ger) e.className=base; },n*140+1900);
    })(CE.gotas[i],i);
  }
}

