  c.appendChild(el("div","balao","Pinte "+(d0.nome||"o desenho")+" do jeito que <b>voc&#234;</b> quiser."));
  c.appendChild(el("div","dica","&#128161; Escolha uma cor e toque no desenho. Pode trocar quantas vezes quiser."));

