  var z=el("button","zap",""); z.appendChild(el("i","fone",""));
  z.setAttribute("aria-label","Ouvir de novo");
  z.onclick=function(){ sTap(); fala("Pinte "+(d0.voz||"o desenho")+" do jeito que você quiser."); };
  f.appendChild(nomeEl); f.appendChild(z);
