function sRisco(){ nota(180,.13,.10,"sawtooth",0); nota(330,.10,.08,"sawtooth",.05); }

function pecaPintar(){
  limpa();
  pintadas=0; erros=0; alvos=[];
  var t=el("div","tela");
  setProg(t,0);
  progI=t.querySelector(".prog i");
  var c=el("div","centro");
  c.appendChild(el("div","selo","MARCA-TEXTO"));
  c.appendChild(el("div","balao","Passe o marca-texto em <b>"+CATEG+"</b> do texto."));

  var pap=el("div","papel"), i, o, s;
  for(i=0;i<TEXTO.length;i++){
    o=TEXTO[i];
    if(o.t!==undefined){ pap.appendChild(document.createTextNode(o.t)); continue; }
    s=el("span","pal",o.p);
    s.setAttribute("data-alvo",o.alvo?"1":"0");
    if(o.alvo){ s.setAttribute("data-qa","1"); alvos.push(s); }
    s.onclick=(function(sp,ehAlvo){ return function(){ tocar(sp,ehAlvo); }; })(s,!!o.alvo);
    pap.appendChild(s);
  }
  c.appendChild(pap);

  elBarra=el("div","barrap");
  c.appendChild(elBarra);
  elPlacar=el("div","p2_placar","");
  c.appendChild(elPlacar);
  elCarimbo=el("div","carimbo","Falta pintar");
  c.appendChild(elCarimbo);
  c.appendChild(el("div","hint","Toque na palavra para passar o marca-texto. Se errar, eu te ajudo."));
  t.appendChild(c);
  app.appendChild(t);
  atualiza();
}

function atualiza(){
  var i,s;
  elBarra.innerHTML="";
  for(i=0;i<alvos.length;i++){
    s=el("div","seg",i<pintadas?"✓":"");
    if(i<pintadas) s.className="seg p2_on";
    elBarra.appendChild(s);
  }
  elPlacar.innerHTML="Pintadas <b>"+pintadas+"</b> de <b>"+alvos.length+"</b>";
  elCarimbo.innerHTML = pintadas===alvos.length ? "Texto todo marcado!"
    : ("Faltam "+(alvos.length-pintadas)+" palavra"+((alvos.length-pintadas)===1?"":"s"));
  if(progI) progI.style.width=Math.round(pintadas*100/alvos.length)+"%";
}

function pinta(sp){
  if(sp.className.indexOf("pintada")>=0) return;
  sp.className="pal pintada";
  sp.removeAttribute("data-qa");
  sp.innerHTML=sp.textContent+'<sup class="vmini">✓</sup>';
  sRisco();
  pintadas++;
  atualiza();
  if(pintadas===alvos.length){ setTimeout(fim,650); }
}

function tocar(sp,ehAlvo){
  if(sp.className.indexOf("pintada")>=0){ sTap(); return; }   /* ja pintada: nunca pune */
  if(ehAlvo){ pinta(sp); return; }
  sErro(); erros++;
  sp.className="pal errada";
  setTimeout((function(x){ return function(){ if(x.className.indexOf("pintada")<0) x.className="pal"; }; })(sp),380);
  ajuda(erros);
}

/* O ANDAIME QUE CRESCE — o erro responde na hora e diz O QUE OLHAR; no 3o toque
   errado ele pinta uma sozinho, entao a peca nao tem como travar. */
function ajuda(n){
  var alvo=proximaPalavra();
  if(!alvo) return;
  var p=n%3;
  if(p===1){ mostraDica("Essa palavra não é um bicho. Procure quem <b>respira e se mexe</b>."); }
  else if(p===2){ mostraDica("Está piscando uma que é bicho. Toque nela."); piscaP(alvo); }
  else { mostraDica("Vou pintar <b>"+alvo.textContent+"</b> para você. Agora ache as outras."); pinta(alvo); }
}
function proximaPalavra(){ var i; for(i=0;i<alvos.length;i++){ if(alvos[i].className.indexOf("pintada")<0) return alvos[i]; } return null; }
function piscaP(sp){
  if(sp.className.indexOf("pintada")>=0) return;
  sp.className="pal p2_pisca";
  setTimeout((function(x){ return function(){ if(x.className.indexOf("pintada")<0) x.className="pal"; }; })(sp),2200);
}

